SELECT COUNT(DISTINCT struct_pack(kind := 0::UTINYINT, value := t0.s, datatype := NULL::VARCHAR, lang := NULL::VARCHAR)) AS "count_result" FROM triples t0, triples t1, triples t2 WHERE t0.p = 'http://purl.org/ontology/mo/conductor' AND struct_pack(kind := 0::UTINYINT, value := t1.s, datatype := NULL::VARCHAR, lang := NULL::VARCHAR) = struct_pack(kind := 0::UTINYINT, value := t0.s, datatype := NULL::VARCHAR, lang := NULL::VARCHAR) AND t1.p = 'http://www.w3.org/1999/02/22-rdf-syntax-ns#type' AND struct_pack(kind := 0::UTINYINT, value := t2.s, datatype := NULL::VARCHAR, lang := NULL::VARCHAR) = struct_pack(kind := 0::UTINYINT, value := t0.s, datatype := NULL::VARCHAR, lang := NULL::VARCHAR) AND t2.p = 'http://db.uwaterloo.ca/~galuc/wsdbm/hasGenre' AND t2.o = struct_pack(kind := 0::UTINYINT, value := 'http://db.uwaterloo.ca/~galuc/wsdbm/SubGenre83', datatype := NULL::VARCHAR, lang := NULL::VARCHAR)